/**
 * TONIO TOWN町政記録 — 「生きている町」の状態データ
 *
 * ■ 生きている、の実装
 * APIもcronも使わない。とにおが「今日の町」と指示する → TOWN_DAYS の先頭に1件追記する。
 * 材料は必ず実データから取る: 前夜のレッスン(第N夜) / 新聞の最新号 / 図鑑の新入り。
 * 捏造は禁止。町のゴシップも、出典が言えるものだけ書く。
 *
 * ■ 日付の規則(重要)
 * 1件のエントリは「レッスンの翌朝」である。第N夜が 8/2 なら、その物理が着弾する町は 8/3。
 * だから夜に書いた時点で先頭は明日の日付になる。表示は latestDay() が日付で絞るので、
 * 書いた朝が来るまで伏せられ、日が変わると勝手に入れ替わる。追記=予約投稿になる。
 *
 * ■ 住所
 * 147人分を手書きしない。所属(circle)ごとに通りを決め、idのハッシュで番地を振る。
 * 決定的なので、リロードしても引っ越さない。
 *
 * ■ 祭り
 * 22シナリオはそのまま町の年中行事である。新しく発明しない。
 */

import { PEOPLE, type WorldPerson } from './requiem-world';

/** 所属ごとの通り。住所 = ハッシュ番地 + この通り */
export const STREETS: Record<string, string> = {
    'vance': 'Maple Street',
    'boyd': 'Birch Lane',
    'hoa': 'Alder Court',
    'chris-carol': 'Route 9 (the farmhouse)',
    'lincoln-high': 'Cedar Row',
    'ridgeway-general': 'Mercy Street',
    'courthouse': 'Court Street',
    'dmv-branch': 'Grange Road',
    'crew-cruise': 'The Marina',
    'road': 'Route 66 (out of town)',
    'campus': 'College Dorms (2 hours away)',
};

export function hashStr(s: string): number {
    let h = 2166136261;
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
    return Math.abs(h);
}

export function addressOf(p: WorldPerson): string {
    const street = STREETS[p.circle] ?? 'Tonio Town';
    if (p.circle === 'chris-carol') return street;
    if (p.circle === 'crew-cruise' || p.circle === 'road' || p.circle === 'campus') return street;
    return `${(hashStr(p.id) % 38) + 2} ${street}`;
}

