/**
 * 本日の町。
 *
 * TOWN_DAYS は「夜のレッスン → 翌朝の町」で書くので、今夜ぶんを書いた時点で
 * 先頭は明日の日付になる。先頭を無条件に出すと、8/2 の夜に 8/3 の朝が始まる。
 * 日付が来ていない朝は伏せておき、日が変わったら勝手に入れ替わる — 毎朝の追記が
 * 「予約投稿」になるので、書く時刻と町が動く時刻を切り離せる。
 */
export function latestDay(): TownDay {
    const d = new Date();
    const p = (n: number) => String(n).padStart(2, '0');
    const today = `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
    return TOWN_DAYS.find((x) => x.date <= today) ?? TOWN_DAYS[TOWN_DAYS.length - 1];
}

/** 予約ぶんも含めた最新の朝(編集・確認用) */
export function newestDay(): TownDay { return TOWN_DAYS[0]; }

export function personById(id: string): WorldPerson | undefined { return PEOPLE.find((p) => p.id === id); }
